node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const reminders = db.prepare('SELECT * FROM ts_reminders').all();

// Show all reminders with human-readable timestamps
reminders.forEach(r => {
  const created = new Date(r.creation_timestamp * 1000);
  const remind = new Date(r.reminder_timestamp * 1000);
  const gap = r.reminder_timestamp - r.creation_timestamp;
  const gapHours = gap / 3600;
  console.log('---');
  console.log('ID:', r.reminder_id);
  console.log('Content:', r.content);
  console.log('Creation:', created.toISOString(), '(', r.creation_timestamp, ')');
  console.log('Reminder:', remind.toISOString(), '(', r.reminder_timestamp, ')');
  console.log('Gap:', gap, 'seconds =', gapHours, 'hours');
});
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// The existing 'Lunch with Jordan' reminder
const existing = db.prepare(\"SELECT * FROM ts_reminders WHERE reminder_id = 'a9e934a7-a20f-4401-a151-6c178b4c43d4'\").get();

const creation = existing.creation_timestamp;
const reminder = existing.reminder_timestamp;
const gap = reminder - creation;

console.log('=== Existing Reminder ===');
console.log('Content:', existing.content);
console.log('Creation timestamp:', creation, '->', new Date(creation * 1000).toISOString());
console.log('Reminder timestamp:', reminder, '->', new Date(reminder * 1000).toISOString());
console.log('');
console.log('=== Time Gap ===');
console.log('Gap:', gap, 'seconds');
console.log('Gap:', gap/3600, 'hours');
console.log('Gap:', Math.floor(gap/3600) + 'h ' + ((gap%3600)/60) + 'm');
console.log('');

// Apply that gap to NOW for the new reminder
const now = Math.floor(Date.now() / 1000);
const newReminderTimestamp = now + gap;
console.log('=== New Reminder ===');
console.log('New creation (now):', now, '->', new Date(now * 1000).toISOString());
console.log('New reminder_timestamp:', newReminderTimestamp, '->', new Date(newReminderTimestamp * 1000).toISOString());
"

node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

// Existing reminder's gap
const existingCreation = 1788228000;
const existingReminder = 1788260400;
const gap = existingReminder - existingCreation; // 32400 seconds = 9 hours

// New reminder: creation = now, reminder = now + gap
const now = Math.floor(Date.now() / 1000);
const newReminderTs = now + gap;
const newId = crypto.randomUUID();

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude)
  VALUES (?, ?, ?, ?, NULL, NULL)
\`).run(newId, 'Lunch with Jordan tomorrow at 12:30.', now, newReminderTs);

console.log('=== New Reminder Created ===');
console.log('ID:', newId);
console.log('Content: Lunch with Jordan tomorrow at 12:30.');
console.log('Creation:', now, '->', new Date(now * 1000).toISOString());
console.log('Reminder:', newReminderTs, '->', new Date(newReminderTs * 1000).toISOString());
console.log('Gap applied:', gap, 'seconds (' + gap/3600 + ' hours)');

// Verify
console.log('');
console.log('=== Verification ===');
const all = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(newId);
console.log(JSON.stringify(all, null, 2));
"

